[579] = { en = "Stormwind Library", tier = 1,
  t = "De bibliotheek van Stormwind",
  p = "Koning Anduin vindt leren heel belangrijk. Daarom heeft hij geld gegeven voor kopieën van verschillende boeken en teksten. Die kopieën zijn voor iedereen. Het is heel simpel. Je brengt me een Library Scrip. Dan geef ik je een kopie van een van de boeken die er zijn.",
