[332] = { en = "Wine Shop Advert", tier = 1,
  t = "Reclame voor de wijnwinkel",
  d = "Als je met iemand over wijn praat, dan weet je het: wij, de Gallina's, verkopen de beste wijn van Stormwind. En we zitten niet ver weg. We zitten ook in het Trade District, aan de mooie grachten van de stad.$B$BHier, neem deze folder. Breng hem naar mijn zus Suzetta in onze winkel. Dan krijg je gratis een fles van onze beroemde pinot noir. Je krijgt er geen spijt van!",
  o = "Ga naar de Gallina Winery en breng Suzetta Gallina het Wine Ticket voor een gratis fles wijn.",
  p = "Hallo en welkom, $N. Heb je al een van onze goede wijnen geproefd?",
  c = "Ah, dus je hebt Renato gezien? Nou, alsjeblieft, meneer. Een fles van onze speciale pinot noir. Je vindt nergens in heel Azeroth een wijn die zo goed is!",
