[333] = { en = "Harlan Needs a Resupply", tier = 1,
  t = "Harlan heeft nieuwe spullen nodig",
  d = "We hebben de laatste tijd veel verkocht. Het lijkt of iedereen harnassen en stevige kleren koopt. Bijna alsof ze een koud, zwaar seizoen verwachten...$B$BMaar dat zijn zorgen voor later. Mijn zorg van vandaag: mijn gebreide kleren zijn bijna op. Ik heb een nieuwe lading van onze leverancier nodig.$B$BWil je deze bestelling naar Rema Schneider brengen, in de Canal Tailor and Fit Shop? Dan ben ik je heel dankbaar.",
  o = "Ga naar de Canal Tailor Shop en breng Rema Schneider de Cloth Request van Harlan Bagley.",
  p = "Heb je een bericht van meneer Bagley?",
  c = "Hier staat dat de zaak van Harlan heel goed loopt. Dat is goed nieuws. Maar ik vraag me af waarom mensen al die harnassen nodig hebben. Ik heb niets gehoord over een open oorlog... Vertellen de edelen ons iets niet?$B$BNou, bedankt dat je de bestelling hebt gebracht. Hier is je betaling. Ik zorg dat Harlan zijn spullen krijgt.",
  g = { {"spullen", "stuff, supplies"}, {"harnassen", "armour (harnas)"}, {"stevige", "sturdy (stevig)"}, {"seizoen", "season"}, {"verwachten", "to expect"}, {"gebreide", "knitted (breien)"}, {"zijn bijna op", "are almost gone, running out"}, {"lading", "load"}, {"leverancier", "supplier"}, {"bestelling", "order, request"}, {"dankbaar", "grateful"}, {"zaak", "business, shop"}, {"vraag me af", "wonder (zich afvragen)"}, {"edelen", "nobles (edele)"}, {"betaling", "payment"} },
},

[334] = { en = "Package for Thurman", tier = 1,
  t = "Een pakje voor Thurman",
  d = "Mijn zoon Thurman is leerling bij Larson Clothiers, in de Mage's Quarter. Hij had vandaag haast en is zijn schaar en naalden vergeten. Ik weet dat een geweldige $C zoals jij belangrijke taken heeft. Maar zonder zijn gereedschap kan Thurman zijn werk als leerling niet doen!$B$BAlsjeblieft, $N. Wil je de naaiset naar mijn zoon brengen? Larson Clothiers is een van de twee kledingwinkels in de Mage's Quarter. Het is de winkel die verder naar binnen ligt, bij de Mage's Tower.",
  o = "Ga naar Larson Clothiers in de Stormwind Mage Quarter en geef Thurman Schneider zijn Sewing Kit.",
  p = "Kom je kleren kopen?",
  c = "O, verdorie! Ik dacht dat ik niet hoefde te werken als ik mijn set vergat. Nu moet ik de Larsons dus toch helpen met naaien...$B$BNou ja. Plezier komt later, denk ik.",
  g = { {"pakje", "small package"}, {"leerling", "apprentice, pupil"}, {"haast", "hurry"}, {"schaar", "scissors, shears"}, {"naalden", "needles (naald)"}, {"geweldige", "great (geweldig)"}, {"taken", "tasks (taak)"}, {"gereedschap", "tools"}, {"naaiset", "sewing kit"}, {"kledingwinkels", "clothing shops (kledingwinkel)"}, {"verdorie", "blast, darn"}, {"naaien", "sewing, to sew"}, {"plezier", "fun"} },
},

[353] = { en = "Stormpike's Delivery", tier = 1,
  t = "Een levering voor Stormpike",
  d = "De Stormpikes zijn een gerespecteerde dwergenclan. Ze staan bekend om hun goede en verfijnde smaak. Het is dus geen wonder dat Gringer Stormpike, een Mountaineer van Ironforge, mij een wapen liet maken.$B$BHet wapen is klaar, maar... Mountaineer Stormpike is ver weg, in het verre Loch Modan. Ga je naar het noorden reizen? Wil je dit pakket dan naar hem brengen?$B$BIn zijn laatste bericht zei Mountaineer Stormpike dat hij bij de noordelijke wachttoren in Loch Modan gestationeerd is.",
  o = "Breng het Package for Stormpike naar Mountaineer Stormpike in Loch Modan.",
  p = "Kom je helemaal uit Stormwind? Ik hoor dat het daar beneden in de mensenlanden gevaarlijk wordt, met bandieten en orcs die overal rondlopen. Een perfecte plek om te laten zien wat een $C waard is!",
  c = "Aha! Dus Grimand heeft mijn bijl eindelijk af! Ik wil hem zo graag proberen tegen een paar troggs en kobolds!$b$bHeel erg bedankt, $N. Het was een lange reis voor deze levering. Hier zijn wat munten voor je moeite.",
  g = { {"levering", "delivery"}, {"gerespecteerde", "respected (gerespecteerd)"}, {"dwergenclan", "dwarven clan"}, {"staan bekend om", "are known for (bekendstaan om)"}, {"verfijnde", "refined, discerning (verfijnd)"}, {"smaak", "taste"}, {"geen wonder", "no wonder"}, {"verre", "distant (ver)"}, {"wachttoren", "guard tower"}, {"gestationeerd", "stationed"}, {"mensenlanden", "human lands"}, {"bandieten", "brigands, bandits (bandiet)"}, {"waard", "worth"}, {"bijl", "axe"}, {"moeite", "effort, trouble"} },
},

[399] = { en = "Humble Beginnings", tier = 1,
  t = "Een eenvoudig begin",
  d = "Het lijkt een eeuwigheid geleden dat ik als jongen op de boerderij in Westfall werkte. Ze zeggen dat je nooit terug kunt gaan, en dat is waar. Voor mij is het zelfs dubbel waar: het huis van mijn familie is afgebrand, en dieven hebben het ingenomen.$b$bIk heb met mijn vader gepraat over wat er met een paar van mijn spullen is gebeurd, zoals mijn eerste kompas. Hij kon ze niet redden. Maar hij zegt ook dat ze ergens op de boerderij verstopt moeten zijn.$b$bJe vindt de Alexston Farmstead ten westen van Sentinel Hill. Kun je misschien gaan en het voor me terughalen?",
  o = "Ga naar het huis van Baros Alexston in Westfall en zoek zijn kompas. Breng het daarna terug naar hem op Cathedral Square in Stormwind.",
  p = "$N! Heb je geluk gehad?",
  c = "O, dank je, $N! Ik heb er in de praktijk niets aan, maar het heeft veel gevoelswaarde... Ik hoef het eigenlijk niet te zeggen, maar bedankt dat je het naar me hebt gebracht... Het heeft je zelf ook iets gekost, en dan heb ik het nog niet over de tijd om helemaal naar Westfall te gaan. Ik ben je dankbaar. Neem dit als teken van mijn dank.",
  g = { {"eenvoudig", "humble, simple"}, {"eeuwigheid", "eternity"}, {"boerderij", "farm"}, {"dubbel", "doubly, double"}, {"afgebrand", "burned down (afbranden)"}, {"dieven", "thieves (dief)"}, {"ingenomen", "taken over (innemen)"}, {"kompas", "compass"}, {"redden", "to save, to rescue"}, {"verstopt", "hidden (verstoppen)"}, {"terughalen", "to retrieve, to fetch back"}, {"in de praktijk", "in practice"}, {"gevoelswaarde", "sentimental value"}, {"teken", "token, sign"} },
},

[1097] = { en = "Elmore's Task", tier = 1,
  t = "De opdracht van Elmore",
  d = "Er is een dwergwapensmid in Stormwind, Grimand Elmore. Hij heeft laten weten dat hij hulp nodig heeft met een levering. Ik denk dat hij een pakket naar zijn thuisland in het noorden wil sturen.$B$BJij hebt sterke benen! Dus als je zin hebt in wat loopwerk, praat dan met Grimand. We kunnen je hier ook goed gebruiken, maar we moeten ook goede banden houden met de dwergen.$B$BJe vindt Grimand Elmore in de wapenwinkel in het Dwarven District van Stormwind, in het noordoosten van de stad.",
  o = "Praat met Grimand Elmore.",
  c = "Kom je helpen met mijn levering? Heel goed!",
  g = { {"opdracht", "task, assignment"}, {"dwergwapensmid", "dwarven weaponsmith"}, {"laten weten", "sent word, let know"}, {"levering", "delivery"}, {"thuisland", "homeland"}, {"sturen", "to send"}, {"benen", "legs (been)"}, {"zin hebt in", "feel like, are interested in (zin hebben in)"}, {"loopwerk", "legwork"}, {"banden", "ties, bonds (band)"}, {"wapenwinkel", "weapon shop"}, {"noordoosten", "northeast"} },
},

[343] = { en = "Speaking of Fortitude", tier = 2,
  t = "Over standvastigheid",
  d = "Ik geef een toespraak over de Standvastigheid van de Geest. Ik wil daarin stukken voorlezen uit een bepaald boek over metaalkunde: \"The Stresses of Iron\". Er hoort een exemplaar van dit boek in de Royal Library te zijn, in Stormwind Keep. Kun je het voor me halen? Als dat lukt, dan is de zegen van het Licht met je!$B$BDe Royal Library is heel groot, maar de hoofdbibliothecaris, Milton Sheaf, kent elke plank alsof het zijn eigen zoon is. Praat met hem. Hij haalt het boek voor je.",
  o = "Ga naar de Royal Library in Stormwind Keep en praat met Milton Sheaf. Hij kan het boek over metaalkunde vinden dat Brother Kristoff nodig heeft voor zijn toespraak.",
  c = "Metaalkunde? O ja, we hebben veel boeken over dat onderwerp. We helpen Brother Kristoff graag met zijn toespraak! Nou... welk boek had de goede broeder ook alweer nodig?",
  g = { {"standvastigheid", "fortitude, steadfastness"}, {"toespraak", "speech"}, {"Geest", "spirit"}, {"voorlezen", "to read aloud, to recite"}, {"bepaald", "particular, certain"}, {"metaalkunde", "metallurgy"}, {"exemplaar", "copy (of a book)"}, {"zegen", "blessing"}, {"hoofdbibliothecaris", "head librarian"}, {"plank", "shelf"}, {"onderwerp", "subject"}, {"broeder", "brother (in a religious order)"}, {"ook alweer", "again (when trying to remember)"} },
},

[344] = { en = "Brother Paxton", tier = 2,
  t = "Brother Paxton",
  d = "The Stresses of Iron? Ja, dat boek ken ik. Een heel goed boek, een paar tientallen jaren geleden geschreven door de dwergenmijnwerker Margulf Blaggon. Hij zat bijna altijd diep in de bergen van Khaz Modan om erts te graven. Slimme kerel!$B$BMaar waar had ik het over? O ja, The Stresses of Iron! Ik ben bang dat het boek naar Northshire Abbey is gebracht. De beheerder van de bibliotheek van de abdij, Brother Paxton, wilde een kopie van het boek maken voor zijn eigen planken.$B$BMaar dat was maanden geleden. Ik vraag me af waarom het hem zo lang duurt...",
  o = "Praat met Brother Paxton in Northshire Abbey.",
  c = "Vraagt meneer Sheaf zich af waar zijn boek is? Nou, dit is een beetje gênant. Ik heb het boek, maar ik ben nog bezig met mijn kopie. Ik ben nog niet helemaal klaar om het origineel terug te geven!",
  g = { {"tientallen jaren", "decades"}, {"dwergenmijnwerker", "dwarven miner"}, {"erts", "ore"}, {"graven", "to dig"}, {"kerel", "fellow, guy"}, {"ik ben bang", "I'm afraid"}, {"beheerder", "caretaker, keeper"}, {"abdij", "abbey"}, {"planken", "shelves (plank)"}, {"vraag me af", "wonder (zich afvragen)"}, {"gênant", "embarrassing"}, {"origineel", "original"} },
},

[345] = { en = "Ink Supplies", tier = 2,
  t = "Een voorraad inkt",
  d = "Ik wilde mijn kopie van The Stresses of Iron al een tijd afmaken, maar...$B$BKijk, ik maak zelf de inkt voor de boeken die ik kopieer. Het is mijn eigen recept. De inkt loopt niet uit, hij vlekt niet en hij droogt heel snel. Helaas droogt hij té snel! Mijn laatste portie was al droog voordat ik klaar was met kopiëren. En ik heb nog geen tijd gehad om nieuwe inkt te maken!$B$BOm meer te maken heb ik Rethban Iron Ore nodig uit de Redridge Mountains. Foreman Oslow in Lakeshire levert het meestal aan mij.",
  o = "Praat met Foreman Oslow in Lakeshire en vraag hem om Rethban Iron Ore.",
  c = "Wat heb je nodig?? Misschien heb je het niet gezien, maar we hebben het druk. We versterken de verdediging van Lakeshire en we herstellen de schade van de laatste aanvallen van de orcs. Als je Rethban Iron Ore nodig hebt, moet je het zelf halen!",
  g = { {"voorraad", "supply, stock"}, {"afmaken", "to finish"}, {"recept", "recipe"}, {"loopt niet uit", "doesn't run (uitlopen)"}, {"vlekt", "smears, stains (vlekken)"}, {"helaas", "unfortunately"}, {"portie", "batch, portion"}, {"kopiëren", "copying, to copy"}, {"levert", "supplies, delivers (leveren)"}, {"versterken", "to fortify, to strengthen"}, {"verdediging", "defences"}, {"herstellen", "to repair"}, {"schade", "damage"}, {"aanvallen", "attacks (aanval)"} },
},

[346] = { en = "Return to Kristoff", tier = 2,
  t = "Terug naar Kristoff",
  d = "Nu ik klaar ben met het overschrijven van het boek, krijg je hier het origineel van The Stresses of Iron. Bedankt voor je geduld. En als je Milton ziet, zeg hem dan alsjeblieft dat het me spijt dat het zo lang heeft geduurd.",
  o = "Ga terug naar Brother Kristoff op Cathedral Square. Geef hem het boek The Stresses of Iron.",
  p = "Heb je het boek kunnen vinden?",
  c = "Dat is het! Dank je, $N. Ik hoop dat het Licht helder schijnt op je lichaam en je geest!",
  g = { {"overschrijven", "copying (by hand)"}, {"origineel", "original"}, {"geduld", "patience"}, {"het me spijt", "I'm sorry (het spijt me)"}, {"geduurd", "taken, lasted (duren)"}, {"helder", "brightly, clear"}, {"schijnt", "shines (schijnen)"}, {"lichaam", "body"}, {"geest", "spirit, mind"} },
},

[347] = { en = "Rethban Ore", tier = 2,
  t = "Rethban-erts",
  d = "Rethban Ore is genoemd naar de man die het als eerste vond, Bart Rethban. Als je het smelt, is het niet zo sterk als ijzer. Maar het erts heeft een donkere, matte kleur, en sommige kopiisten gebruiken het in hun kleurstoffen. Je vindt het in de Rethban Caverns, ten noorden van hier.$B$BMeestal hebben we wat op voorraad, maar we hebben het te druk met de voorbereiding op aanvallen van orcs om iets te verzamelen. En trouwens... Redridge Gnolls wonen nu in de Rethban Caverns, en hun Drudgers verzamelen het erts zelf.$B$BDus als je wat nodig hebt, moet je het zelf halen.",
  o = "Verzamel 5 ladingen Rethban Ore en breng ze naar Brother Paxton in de Northshire Library.",
  p = "Heb je het Rethban Ore?",
  c = "O, prachtig! Met dit erts kan ik mijn kleurstof maken, en dan kan ik het overschrijven van The Stresses of Iron afmaken.$B$BDank je, $N!",
  g = { {"genoemd naar", "named after"}, {"smelt", "smelt, melt (smelten)"}, {"ijzer", "iron"}, {"matte", "flat, dull (mat)"}, {"kopiisten", "scribes, copyists (kopiist)"}, {"kleurstoffen", "dyes (kleurstof)"}, {"op voorraad", "in stock"}, {"voorbereiding", "preparation"}, {"verzamelen", "to gather"}, {"trouwens", "besides, by the way"}, {"ladingen", "loads (lading)"}, {"prachtig", "splendid"}, {"kleurstof", "dye"} },
},

[1241] = { en = "The Missing Diplomat", tier = 2,
  t = "De verdwenen diplomaat",
  d = "Kortgeleden werd er een diplomaat naar Theramore gestuurd om Jaina Proudmoore te ontmoeten. Die diplomaat is daar nooit aangekomen.$B$BIk denk dat de Defias bij dit complot betrokken zijn, maar ik weet niet hoe. Het publiek weet nog niets van de verdwijning van de diplomaat, maar dat kan niet lang zo blijven.$B$BAgenten van de koning zoeken de stad al af naar aanwijzingen, maar ik wil ook mijn eigen contacten erbij betrekken.$B$BIn de Valley of Heroes is een oude vriend van me, Jorgen. Zoek hem, geef hem dit briefje en volg zijn instructies.",
  o = "Zoek Jorgen in Stormwind City.",
  p = "Hm, je kunt maar beter een goede reden hebben om een man te storen terwijl hij vist. Ik hou niet van venters, en al helemaal niet van bedelaars.",
  c = "Hm... <Jorgen kijkt je met half dichtgeknepen ogen aan.>$b$bGoed. Ik help je, maar niet omdat ik het wil. Ik help je omdat ik het verplicht ben.$b$bEn laten we één ding duidelijk maken: je weet nu al veel meer dan je zou moeten weten. Laten we dit ons kleine geheimpje houden. Ga in de kroegen niet rondkletsen over wat je ontdekt. Begrepen?",
  g = { {"verdwenen", "missing, disappeared (verdwijnen)"}, {"diplomaat", "diplomat"}, {"complot", "plot, conspiracy"}, {"betrokken", "involved"}, {"verdwijning", "disappearance"}, {"zoeken de stad al af", "are already scouring the city (afzoeken)"}, {"aanwijzingen", "clues (aanwijzing)"}, {"erbij betrekken", "to involve, to bring in"}, {"storen", "to disturb, to interrupt"}, {"venters", "peddlers (venter)"}, {"bedelaars", "beggars (bedelaar)"}, {"dichtgeknepen", "squinted (dichtknijpen)"}, {"verplicht", "obliged"}, {"kroegen", "taverns, pubs (kroeg)"}, {"rondkletsen", "to blab, to gossip around"} },
},

[1242] = { en = "The Missing Diplomat", tier = 2,
  t = "De verdwenen diplomaat",
  d = "Breng dit briefje naar Elling Trias. Zeg verder niks tegen hem. Wees gewoon beleefd en wacht tot hij reageert. En maak je geen zorgen, dat doet hij heus.$B$BIk zeg het je nog maar één keer, $N: neem deze zaak serieus en hou je kwebbel dicht.$B$BJe vindt Trias in zijn kaaswinkel, Trias' Cheese, in het Trade District. Succes.",
  o = "Breng Jorgen's Sealed Note naar Elling Trias in Stormwind City.",
  p = "Hallo, $N. Kan ik iets voor je doen? Wil je misschien onze speciale Trias-cheddar proeven? Of een blok Darnassian bleu?",
  c = "Pardon, een brief voor mij? Nou, wie had dat gedacht... Je krijgt niet vaak een levering die geen krat of vat is, als je alleen maar werkt. Eens kijken waar dit over gaat.$B$B<Elling kijkt naar je terwijl hij de brief openmaakt.>$B$BJe ziet er een beetje gespannen uit. Gaat het wel, $N?",
  g = { {"briefje", "note"}, {"beleefd", "polite"}, {"reageert", "responds (reageren)"}, {"heus", "really, certainly"}, {"zaak", "matter, affair"}, {"serieus", "seriously"}, {"hou je kwebbel dicht", "keep your yapper shut"}, {"kaaswinkel", "cheese shop"}, {"proeven", "to taste, to try"}, {"blok", "block"}, {"wie had dat gedacht", "well I'll be, who'd have thought"}, {"krat", "crate"}, {"vat", "barrel"}, {"gespannen", "tense"} },
},

[1243] = { en = "The Missing Diplomat", tier = 2,
  t = "De verdwenen diplomaat",
  d = "Jorgen, ouwe schoft... Dus zo gaat het worden, hè?$B$BGoed, daar kan ik mee leven. Ik hoop dat hij daardoor nog eerder in de Twisting Nether terechtkomt!$B$BDit is wat er gaat gebeuren, $N. Ik ga mijn contacten hier gebruiken, maar jij doet het meeste loopwerk, zodat ik wat geld bespaar.$B$BGa naar Darkshire in Duskwood en zoek Watcher Backus. Hij loopt meestal patrouille op de weg naar het noorden, net buiten het dorp. Zeg hem gewoon dat je voor mij uitzoekt wat de Defias doen. Dan helpt hij je met alle informatie die hij heeft.",
  o = "Geef de Sealed Note aan Watcher Backus in Duskwood.",
  p = "Het is niet zo veilig om door de bossen te reizen, $N. Wees voorzichtig. Zie je iets verdachts of gevaarlijks? Waarschuw dan meteen de Watchers. Probeer niets alleen aan te pakken. Wij zijn niet verantwoordelijk voor iets vreselijks dat jou kan overkomen.$B$BMaar we weten allebei dat je niet naar me gaat luisteren. Je gaat toch vechten tegen alles wat uit het donker komt, of niet? Haha, ja, jullie avonturiers... allemaal hetzelfde.",
  c = "O, heeft Trias je gestuurd? Dat is iets anders.$B$BVecht gerust tegen alle monsters die uit het donker op je afkomen. Ik weet zeker dat je ze vrij makkelijk aankunt, als je omgaat met types zoals hij.$B$BDus, wat heeft mijn vriend van me nodig op zo'n sombere dag als vandaag?",
  g = { {"ouwe schoft", "old so-and-so, old rascal"}, {"terechtkomt", "ends up (terechtkomen)"}, {"loopwerk", "legwork"}, {"bespaar", "save (besparen)"}, {"loopt ... patrouille", "patrols (patrouille lopen)"}, {"uitzoekt", "are looking into (uitzoeken)"}, {"verdachts", "suspicious (verdacht)"}, {"waarschuw", "warn, alert (waarschuwen)"}, {"aan te pakken", "to take on (aanpakken)"}, {"verantwoordelijk", "responsible"}, {"overkomen", "to happen to"}, {"avonturiers", "adventurers (avonturier)"}, {"gerust", "feel free, by all means"}, {"aankunt", "can handle (aankunnen)"}, {"sombere", "gloomy (somber)"} },
},

[1274] = { en = "The Missing Diplomat", tier = 2,
  t = "De verdwenen diplomaat",
  d = "Pardon, $gmeneer:mevrouw;. Bishop DeLavey heeft me gevraagd om avonturiers aan te spreken die hem misschien kunnen helpen met een gevoelige zaak.$B$BKun je zonder op te vallen naar Stormwind Keep gaan en met hem praten, zodra het je uitkomt? Ik weet zeker dat hij je hulp zal waarderen. Nogmaals: wees alsjeblieft discreet. Het is een zaak van enig belang.",
  o = "Zoek Bishop DeLavey in Stormwind Keep.",
  c = "Hallo, $N. Ik ben Bishop DeLavey.$B$BAls je mij vraagt wat ik hier in de burcht doe, dan is het de jonge Thomas zeker gelukt om jou in te schakelen om ons koninkrijk te helpen. Hij is altijd goed geweest in het uitvoeren van mijn verzoeken.$B$BHelaas heb ik geen tijd om veel uit te leggen. Dus laat me direct zijn... en probeer alsjeblieft te voorkomen dat iedereen dit te weten komt.",
  g = { {"aan te spreken", "to approach, to address (aanspreken)"}, {"gevoelige", "delicate, sensitive (gevoelig)"}, {"zonder op te vallen", "without drawing attention, quietly"}, {"zodra het je uitkomt", "at your earliest convenience"}, {"waarderen", "to appreciate"}, {"nogmaals", "once again"}, {"discreet", "discreet"}, {"belang", "importance"}, {"burcht", "keep, castle"}, {"in te schakelen", "to enlist, to bring in (inschakelen)"}, {"koninkrijk", "kingdom"}, {"uitvoeren", "carrying out"}, {"verzoeken", "requests (verzoek)"}, {"voorkomen", "to prevent"}, {"te weten komt", "finds out (te weten komen)"} },
},

[392] = { en = "The Curious Visitor", tier = 2,
  t = "De vreemde bezoeker",
  d = "In de eerste jaren dat Thredd gevangen zat, kreeg hij nooit bezoek. Ik dacht dat hij niet meer nuttig was voor de Brotherhood, en dat ze hem daarom in de steek hadden gelaten.$B$BHoe dan ook, een paar maanden geleden veranderde dat allemaal. Hij kreeg regelmatig bezoek... één keer, misschien twee keer per week. Het was een vreemde man, het stille type. Ik vertrouwde het niet, maar al zijn papieren waren in orde.$B$BVolgens zijn documenten heette hij Maelik. Hier is zijn beschrijving. Ik denk niet dat hij Thredd nog komt bezoeken.",
  o = "Breng de Sealed Description of Thredd's Visitor naar Baros Alexston in Stormwind.",
  p = "Ja, $N? Wat heb je gevonden?",
  c = "Hm. Maelik? Nee, die naam klinkt niet bekend, en deze beschrijving ook niet. Maar het kan iedereen zijn! Een vroegere Stonemason, iemand van de Defias Brotherhood... Maar als hij zo goede connecties heeft als Thelwater denkt, dan herkent iemand anders hem misschien. Even denken.",
  g = { {"bezoeker", "visitor"}, {"gevangen zat", "was imprisoned (gevangen zitten)"}, {"nuttig", "useful"}, {"in de steek hadden gelaten", "had abandoned (in de steek laten)"}, {"hoe dan ook", "anyway"}, {"regelmatig", "regular(ly)"}, {"vertrouwde het niet", "was suspicious, didn't trust it (vertrouwen)"}, {"in orde", "in order"}, {"volgens", "according to"}, {"beschrijving", "description"}, {"vroegere", "former (vroeger)"}, {"connecties", "connections (connectie)"}, {"herkent", "recognizes (herkennen)"} },
},

[393] = { en = "Shadow of the Past", tier = 2,
  t = "Schaduw van het verleden",
  d = "Ik heb echt geen idee, $N. Er is iemand anders die je misschien kan helpen, en toevallig is hij me nog een gunst schuldig voor... nou, daar gaan we het niet over hebben. Master Mathias Shaw van SI:7 vind je in de kazerne in Old Town. Shaw weet van bijna alle duistere en oneerlijke zaakjes in de stad.$B$BAls iemand het weet, dan is hij het.",
  o = "Breng de Sealed Description of Thredd's Visitor naar Master Mathias Shaw in Stormwind.",
  p = "Gegroet. Wat kan ik voor je doen, $C?",
  c = "Wat? Wat is dit? Ja, ik denk dat ik weet wie deze man is. Maar zijn naam is niet Maelik. Sluipmoordenaars hebben veel namen en veel maskers. Ze gooien ze weg als ze niet meer nuttig zijn. Een andere schuilnaam die deze man gebruikt, is Marzon. Maar ook dat is vast niet zijn echte naam.$b$bHoe dan ook, hij is een sluipmoordenaar en ik weet heel wat over hem.$b$bMarzon werkt op dit moment voor Lord Gregor Lescovar, een heer met een slechte naam, zelfs als je kijkt naar hoe corrupt de adel van Stormwind is.",
  g = { {"verleden", "past"}, {"toevallig", "as it happens, by chance"}, {"gunst", "favour"}, {"schuldig", "owing, indebted"}, {"kazerne", "barracks"}, {"duistere", "shady, dark (duister)"}, {"oneerlijke", "underhanded, dishonest (oneerlijk)"}, {"zaakjes", "dealings (zaakje)"}, {"gegroet", "greetings"}, {"sluipmoordenaars", "assassins (sluipmoordenaar)"}, {"maskers", "masks (masker)"}, {"schuilnaam", "alias"}, {"vast", "surely, no doubt"}, {"corrupt", "corrupt"}, {"adel", "nobility"} },
},

[335] = { en = "A Noble Brew", tier = 2,
  t = "Een edel brouwsel",
  d = "Lord Wishock maakt veel ophef in het House of Nobles. Hij heeft gehoord over ons kleine \"etablissement\" hier beneden, en hij probeert steun te krijgen voor een volledig onderzoek. Ik heb een plan om Wishock \"bezig te houden\", maar daarvoor heb ik jouw hulp nodig.$b$bIn de Garden of Stalvan, aan de rand van Darkshire, groeit een bloem. Dit kleine witte bloempje heet de Tear of Tilloa. Ik heb ook een Musquash Root nodig. Die vind je alleen helemaal onderaan de watervallen, diep onder de Stonewrought Dam in de Wetlands.",
  o = "Zardeth the Black Claw wil dat je hem een Tear of Tilloa uit Darkshire en een Musquash Root uit de Wetlands brengt.",
  p = "Wishock krijgt binnenkort genoeg steun om ons veel last te bezorgen. Heb je de Tear of Tilloa of de Musquash Root al kunnen vinden?",
  c = "Uitstekend! Dit zijn echt mooie exemplaren!",
  g = { {"edel", "noble"}, {"brouwsel", "brew"}, {"ophef", "stir, fuss"}, {"etablissement", "establishment"}, {"steun", "support"}, {"volledig", "full, complete"}, {"onderzoek", "investigation"}, {"bezig te houden", "to keep busy, preoccupied (bezighouden)"}, {"aan de rand van", "on the outskirts of"}, {"bloempje", "little flower"}, {"onderaan", "at the bottom of"}, {"watervallen", "falls, waterfalls (waterval)"}, {"last te bezorgen", "to cause trouble, grief (last bezorgen)"}, {"uitstekend", "excellent"}, {"exemplaren", "samples, specimens (exemplaar)"} },
},

[336] = { en = "A Noble Brew", tier = 2,
  t = "Een edel brouwsel",
  d = "Lord Wishock heeft, zoals alle mannen, zijn zwakke punten. Het zijne is dat hij van drank houdt. De hypocrisie is ongelooflijk. De saaie dwaas besteedt zijn dagen aan pogingen om onze kleine \"taverne\" te sluiten, terwijl hij zijn nachten hierboven doorbrengt. Daar maakt hij een rekening die hij nooit betaalt. Nou, eens kijken hoe Wishock dit speciale brouwsel vindt dat ik voor hem heb gemaakt: Black Claw Stout. Het is behoorlijk sterk, $n.$b$bBreng het naar hem en kijk hoe hij het vindt. Waarschijnlijk loopt de oude dwaas rond in de Hall of Petitioners.",
  o = "Breng de Black Claw Stout naar Lord Wishock in de Hall of Petitioners.",
  p = "Zie je niet dat ik bezig ben? Mijn woorden moeten gehoord worden! Ik ben heel belangrijk voor de toekomst van dit koninkrijk!$B$BO... wat heb je daar? Dat lijkt wel een verfrissend drankje...",
  c = "Ah, bedankt voor deze mooie stout, dienaar. Hier is een koperstuk voor je. En nu, uit mijn ogen, en laat me van mijn drankje genieten!",
  g = { {"zwakke punten", "weaknesses"}, {"drank", "liquor, drink"}, {"hypocrisie", "hypocrisy"}, {"ongelooflijk", "astounding, unbelievable"}, {"saaie", "trite, dull (saai)"}, {"dwaas", "fool"}, {"pogingen", "attempts (poging)"}, {"doorbrengt", "spends (doorbrengen)"}, {"rekening", "bill, tab"}, {"behoorlijk", "quite, pretty"}, {"waarschijnlijk", "most likely"}, {"verfrissend", "refreshing"}, {"dienaar", "servant"}, {"koperstuk", "copper coin"}, {"uit mijn ogen", "out of my sight"} },
},

[397] = { en = "You Have Served Us Well", tier = 2,
  t = "Je hebt ons goed gediend",
  d = "Ik hoor dat Lord Wishock van zijn drankje heeft genoten.$b$bJe hebt ons goed gediend, $N. Dankzij jou kunnen de heksenmeesters van Stormwind onze kunst beoefenen zonder dat iemand ons stoort. Voor je moeite heb ik een speciaal cadeau voor je klaargemaakt. Praat met mijn dienaar, Zggi, en haal je beloning op.",
  o = "Praat met Zggi, de dienaar van Zardeth the Blackclaw, om je beloning op te halen.",
  c = "Meester zegt: geef cadeau aan $N. Zggi wil mooi cadeau houden, maar Zggi is niet zo dom om Meester te verraden.",
  g = { {"gediend", "served (dienen)"}, {"genoten", "enjoyed (genieten)"}, {"dankzij", "thanks to"}, {"heksenmeesters", "warlocks (heksenmeester)"}, {"kunst", "art, craft"}, {"beoefenen", "to practise"}, {"stoort", "disturbs (storen)"}, {"cadeau", "gift"}, {"klaargemaakt", "prepared (klaarmaken)"}, {"dienaar", "servant"}, {"beloning", "reward"}, {"haal ... op", "collect, claim (ophalen)"}, {"verraden", "to betray"} },
},

[1244] = { en = "The Missing Diplomat", tier = 2,
  t = "De verdwenen diplomaat",
  d = "Activiteit van de Defias? Nou, er is altijd wel wat activiteit. Zelfs als ze op zichzelf blijven, zien we ze als een bedreiging.$B$BMaar nu ik erover nadenk: kortgeleden is er iets gezien dat vreemd leek. Het was een paar weken geleden, denk ik, maar een aantal van hun agenten had zich verzameld bij Addle's Stead. Door het verslag dacht ik dat er iets groots was gebeurd.$B$BWaarom kijk je daar niet eerst, en breng je me alles wat je vindt?$B$BDe boerderij ligt ten zuiden van de weg uit Westfall, net waar je Duskwood binnenkomt.",
  o = "Vind de Defias Docket en breng hem terug naar Watcher Backus in Duskwood.",
  p = "Wees voorzichtig daarbuiten, $N. Ik weet dat Trias je hierheen heeft gestuurd, maar dat betekent niet dat er niets in de bossen rondsluipt dat je problemen kan bezorgen... zeker nu je de Defias onderzoekt.",
  c = "Je bent heelhuids terug. Meer kun je niet vragen, toch?$B$BNou, eens kijken wat we hier hebben. Dit ziet er heel officieel uit, vergeleken met andere Defias-documenten die ik heb gezien. Maar het kan ook nep zijn, om je op een dwaalspoor te brengen, weg van wat je zoekt.",
  g = { {"activiteit", "activity"}, {"op zichzelf blijven", "keep to themselves"}, {"bedreiging", "threat"}, {"nadenk", "think about (nadenken)"}, {"agenten", "agents (agent)"}, {"verzameld", "gathered (zich verzamelen)"}, {"verslag", "report"}, {"binnenkomt", "enter (binnenkomen)"}, {"rondsluipt", "lurks, sneaks around (rondsluipen)"}, {"bezorgen", "to cause"}, {"onderzoekt", "are investigating (onderzoeken)"}, {"heelhuids", "safe and sound"}, {"officieel", "official"}, {"nep", "fake, a dupe"}, {"op een dwaalspoor te brengen", "to throw off track (op een dwaalspoor brengen)"} },
},

[1245] = { en = "The Missing Diplomat", tier = 2,
  t = "De verdwenen diplomaat",
  d = "Wauw, dit is veel te ingewikkeld om alleen maar bedoeld te zijn om je op het verkeerde pad te zetten. Ik zou hier niet eens naar mogen kijken. Breng het naar Trias. Hij kan het wel begrijpen. En laat NIEMAND je tegenhouden. Dit is groter dan ik. Het is misschien zelfs groter dan hij, maar dat zien we nog wel.$B$BEn doe me een plezier, $N: vertel niemand dat ik je heb geholpen. Als mijn bazen erachter kwamen dat ik hiervan wist en het niet met hen deelde, dan zouden ze me waarschijnlijk ophangen.",
  o = "Breng de Defias Docket naar Elling Trias in Stormwind.",
  p = "Ik zie dat je terug bent, en in één stuk. We weten allebei dat je hier niet voor kaas bent, dus laten we de beleefdheden overslaan. Had je iets aan Backus, of ben je nog niet eens naar Duskwood geweest?",
  c = "Ja... dit is interessant om te lezen. Jorgen en DeLavey waren slim dat ze mij erbij haalden.$B$BHet lijkt erop dat de Defias erg hun best doen om dit plan van hen af te maken. Hm... wat is dit? Fist? Die naam ken ik.",
  g = { {"ingewikkeld", "complex, complicated"}, {"bedoeld", "meant, intended (bedoelen)"}, {"op het verkeerde pad te zetten", "to lead astray"}, {"tegenhouden", "to stop, to get in the way"}, {"doe me een plezier", "do me a favour"}, {"bazen", "bosses, superiors (baas)"}, {"erachter kwamen", "found out (erachter komen)"}, {"deelde", "shared (delen)"}, {"ophangen", "to hang"}, {"in één stuk", "in one piece"}, {"beleefdheden", "pleasantries (beleefdheid)"}, {"overslaan", "to skip"}, {"had je iets aan", "was ... any help (iets hebben aan)"}, {"erbij haalden", "brought in (erbij halen)"}, {"hun best doen", "are trying hard (je best doen)"} },
},

[350] = { en = "Look to an Old Friend", tier = 2,
  t = "Op zoek naar een oude vriend",
  d = "Dat Marzon contact zou hebben met iemand van de Defias, en banden met Lescovar...$B$BNu VanCleef en Thredd gedood zijn, wordt het moeilijk om Lescovar echt voor het gerecht te brengen. Je bewijs is niets waard zonder hun getuigenissen. En dan hebben we het er nog niet eens over dat Lescovar een edelman is met goede connecties. Daardoor staat hij in feite boven de wet.$B$BJe hebt andere hulp nodig. Ik doe het niet graag, maar ik ken iemand die ons zal helpen. Je vindt Trias in het Trade District van de stad.",
  o = "Praat met Elling Trias in Stormwind.",
  c = "Je maakt een grapje? Wil Shaw weer mijn hulp? Wat een brutaliteit...$b$bDe Defias Brotherhood, zeg je? Nou, jij brengt echt geweldig nieuws, hè? Straks ga je me nog vertellen dat Deathwing nog leeft en de stad aanvalt.$b$bGoed, vertel me alles vanaf het begin. En laat niets weg, ook niet als je denkt dat het niet belangrijk is. Ik moet alles weten.",
  g = { {"banden", "ties (band)"}, {"gedood", "killed (doden)"}, {"voor het gerecht te brengen", "to bring to justice"}, {"bewijs", "evidence"}, {"getuigenissen", "testimonies (getuigenis)"}, {"edelman", "nobleman"}, {"connecties", "connections (connectie)"}, {"in feite", "effectively, in fact"}, {"boven de wet", "above the law"}, {"ik doe het niet graag", "I loathe to do so"}, {"grapje", "joke"}, {"brutaliteit", "nerve, cheek"}, {"straks", "next, soon"}, {"laat niets weg", "don't leave anything out (weglaten)"} },
},

[394] = { en = "The Head of the Beast", tier = 2,
  t = "De kop van het beest",
  d = "Zoek Shaw in Old Town. Vertel hem dat het gevaar van Lescovar is opgelost, en vertel hem over jouw rol bij de plannen van de Lord tegen de stad. Ik weet zeker dat hij trots zal zijn op weer een held onder de burgers van Stormwind.$B$BHij stuurt je waarschijnlijk door naar de prins of een andere edelman. Laat het je niet naar je hoofd stijgen, $N. De edelen mogen denken dat ze de stad besturen zoveel ze willen, maar sommige dingen hebben ze niet in de hand.",
  o = "Praat met Mathias Shaw in Stormwind.",
  c = "Hij is dus dood? Jouw gerechtigheid was snel, $N. Ik bid tot het Licht dat ik nooit jouw prooi word!$b$b<Hij lacht en slaat je op je schouder.>$b$bDat is geen kritiek, $N. Hoe zou dat ook kunnen? Ik ben zelf de meester van alle sluipmoordenaars. Maar eerlijk gezegd heb je het volk van Stormwind een grote dienst bewezen, en daarvoor dank ik je.",
  g = { {"beest", "beast"}, {"opgelost", "dealt with, solved (oplossen)"}, {"rol", "part, involvement"}, {"burgers", "citizens (burger)"}, {"stuurt ... door", "sends on (doorsturen)"}, {"naar je hoofd stijgen", "go to your head"}, {"besturen", "to rule, to govern"}, {"in de hand", "in (their) hands, under control"}, {"gerechtigheid", "justice"}, {"bid", "pray (bidden)"}, {"prooi", "prey, quarry"}, {"schouder", "shoulder"}, {"kritiek", "criticism"}, {"eerlijk gezegd", "in truth, honestly"}, {"een grote dienst bewezen", "done a great service (een dienst bewijzen)"} },
},

[395] = { en = "Brotherhood's End", tier = 2,
  t = "Het einde van de Brotherhood",
  d = "Ah, ik was het bijna vergeten. Alexston is langsgekomen toen je weg was. Hij wilde met je praten. Hij wil vast aan de edelen vertellen wat de Defias Brotherhood allemaal uitspookte.$B$BEen goede raad, $N: als iemand ernaar vraagt, zou ik alle details geven, behalve dat het jouw hand was die Lescovar doodde. Geloof me. Ik ben... bekend... met dit soort dingen.$B$BEn wat Trias betreft: praat met niemand over hem... nooit... als het even kan.",
  o = "Praat met Baros Alexston in Stormwind.",
  c = "Fijn je te zien, $N. Ik heb gehoord dat Lord Gregor Lescovar kortgeleden dood is gevonden.$b$bHet lijkt erop dat je missie geslaagd is. Ik ben je dankbaar dat je mij, en vele anderen, hebt gered van de wraak van VanCleef.",
  g = { {"langsgekomen", "came by (langskomen)"}, {"vast", "no doubt, surely"}, {"uitspookte", "was up to (uitspoken)"}, {"raad", "advice"}, {"details", "details (detail)"}, {"behalve", "except"}, {"doodde", "slew, killed (doden)"}, {"bekend met", "acquainted with"}, {"wat Trias betreft", "as far as Trias goes"}, {"als het even kan", "if you can help it"}, {"kortgeleden", "not long ago"}, {"geslaagd", "successful (slagen)"}, {"gered", "saved (redden)"}, {"wraak", "revenge"} },
},

[396] = { en = "An Audience with the King", tier = 2,
  t = "Een audiëntie bij de koning",
  d = "Ik heb een rapport voor de koning gemaakt. Ik vind dat jij het naar hem moet brengen, samen met een verslag van wat je hebt ontdekt. Maak je geen zorgen: hij zal je zeker prijzen omdat je je plicht hebt gedaan voor het volk van Stormwind.$B$BJe audiëntie is binnenkort, dus je kunt beter opschieten. Het is een stukje lopen naar Stormwind Keep.",
  o = "Breng het rapport van Baros Alexston over de Defias Brotherhood naar King Varian Wrynn in Stormwind Keep.",
  p = "$N, ja? Baros Alexston heeft me laten weten dat je zou komen. Ik moet zeggen dat ik erg benieuwd ben naar wat je te zeggen hebt.",
  c = "Je verdient lof voor wat je voor Stormwind hebt gedaan, $N. Als VanCleef was geslaagd met zijn sluwe plannen, dan had hij het koninkrijk ongetwijfeld veel schade gedaan. Dat moeten we natuurlijk voorkomen.$B$BNeem dit aan, $C, als teken van de waardering van de koning. Het spijt me alleen dat hij het niet zelf aan je kan geven. Hij is weg op een diplomatieke missie en komt voorlopig niet terug.",
  g = { {"audiëntie", "audience (with a ruler)"}, {"rapport", "report"}, {"verslag", "account"}, {"prijzen", "to commend, to praise"}, {"plicht", "duty"}, {"opschieten", "to hurry"}, {"een stukje lopen", "a bit of a walk"}, {"benieuwd", "curious, eager to know"}, {"lof", "praise, commendation"}, {"sluwe", "cunning (sluw)"}, {"ongetwijfeld", "no doubt"}, {"schade", "harm, damage"}, {"waardering", "appreciation"}, {"diplomatieke", "diplomatic (diplomatiek)"}, {"voorlopig", "for some time, for now"} },
},

})

